-- En pgAdmin 4, crea primero una base llamada SanitasFlow y conéctate a ella.
-- Después ejecuta este archivo en Query Tool.

CREATE TABLE IF NOT EXISTS "Pacientes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombres" text NOT NULL,
    "ApellidoPaterno" text NOT NULL,
    "ApellidoMaterno" text NOT NULL,
    "Edad" integer NOT NULL,
    "Correo" varchar(320) NOT NULL UNIQUE,
    "PasswordHash" varchar(512) NOT NULL,
    "CreadoEnUtc" timestamp with time zone NOT NULL
);

CREATE TABLE IF NOT EXISTS "Medicos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" text NOT NULL,
    "Especialidad" text NOT NULL,
    "Correo" text NOT NULL
);

CREATE TABLE IF NOT EXISTS "Especialidades" (
    "Id" varchar(450) PRIMARY KEY,
    "Nombre" text NOT NULL,
    "Descripcion" text NOT NULL
);

CREATE TABLE IF NOT EXISTS "Procedimientos" (
    "Id" varchar(450) PRIMARY KEY,
    "EspecialidadId" varchar(450) NOT NULL REFERENCES "Especialidades"("Id") ON DELETE RESTRICT,
    "Nombre" text NOT NULL,
    "Descripcion" text NOT NULL,
    "DuracionMin" integer NOT NULL,
    "Precio" numeric(10,2) NOT NULL
);

CREATE TABLE IF NOT EXISTS "Citas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PacienteId" integer NOT NULL REFERENCES "Pacientes"("Id") ON DELETE CASCADE,
    "EspecialidadId" varchar(450) NOT NULL REFERENCES "Especialidades"("Id") ON DELETE RESTRICT,
    "ProcedimientoId" varchar(450) NOT NULL REFERENCES "Procedimientos"("Id") ON DELETE RESTRICT,
    "Fecha" date NOT NULL,
    "InicioMin" integer NOT NULL,
    "FinMin" integer NOT NULL,
    "Motivo" text NOT NULL,
    "Precio" numeric(10,2) NOT NULL,
    "Estado" varchar(32) NOT NULL,
    "CreadaEnUtc" timestamp with time zone NOT NULL,
    "MotivoCancelacion" varchar(1000),
    "DeseaReagendar" boolean NOT NULL DEFAULT FALSE,
    "CanceladaEnUtc" timestamp with time zone,
    "PorcentajeReembolso" integer,
    "MontoReembolso" numeric(10,2),
    CONSTRAINT "CK_Citas_Horario" CHECK ("FinMin" > "InicioMin")
);

-- Actualiza bases existentes sin borrar citas ni pagos.
ALTER TABLE "Citas" ADD COLUMN IF NOT EXISTS "MotivoCancelacion" varchar(1000);
ALTER TABLE "Citas" ADD COLUMN IF NOT EXISTS "DeseaReagendar" boolean NOT NULL DEFAULT FALSE;
ALTER TABLE "Citas" ADD COLUMN IF NOT EXISTS "CanceladaEnUtc" timestamp with time zone;
ALTER TABLE "Citas" ADD COLUMN IF NOT EXISTS "PorcentajeReembolso" integer;
ALTER TABLE "Citas" ADD COLUMN IF NOT EXISTS "MontoReembolso" numeric(10,2);

CREATE INDEX IF NOT EXISTS "IX_Citas_EspecialidadId_Fecha" ON "Citas"("EspecialidadId", "Fecha");

CREATE TABLE IF NOT EXISTS "Pagos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CitaId" integer NOT NULL REFERENCES "Citas"("Id") ON DELETE CASCADE,
    "Monto" numeric(10,2) NOT NULL,
    "Metodo" text NOT NULL,
    "Estado" text NOT NULL,
    "ReferenciaExterna" text NOT NULL,
    "CreadoEnUtc" timestamp with time zone NOT NULL
);

-- Registra los montos de donativos. No almacena datos de tarjetas ni procesa cargos.
CREATE TABLE IF NOT EXISTS "Donativos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Monto" numeric(10,2) NOT NULL CHECK ("Monto" >= 10 AND "Monto" <= 100000),
    "Moneda" varchar(3) NOT NULL DEFAULT 'MXN',
    "Estado" varchar(32) NOT NULL DEFAULT 'Registrado',
    "CreadoEnUtc" timestamp with time zone NOT NULL
);
